const UNITS = { h: 3600000, m: 60000, s: 1000, ms: 1 };

export function parseDuration(text) {
  if (!text) throw new Error(`bad duration: ${text}`);
  const parts = text.match(/\d+(?:ms|[hms])/g);
  if (!parts || parts.join('').length !== text.length) {
    throw new Error(`bad duration: ${text}`);
  }
  return parts.reduce((sum, part) => {
    const [, n, unit] = /^(\d+)(ms|[hms])$/.exec(part);
    return sum + Number(n) * UNITS[unit];
  }, 0);
}

export function parseCsvLine(line) {
  const fields = [];
  let current = '';
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];

    if (inQuotes) {
      if (ch === '"') {
        if (i + 1 < line.length && line[i + 1] === '"') {
          current += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        current += ch;
      }
    } else {
      if (ch === '"') {
        inQuotes = true;
      } else if (ch === ',') {
        fields.push(current);
        current = '';
      } else {
        current += ch;
      }
    }
  }

  fields.push(current);
  return fields;
}

