const NUMERALS = [
  [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'],
  [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'],
  [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I'],
];

const ROMAN_VALUE = new Map([
  ['I', 1], ['V', 5], ['X', 10], ['L', 50],
  ['C', 100], ['D', 500], ['M', 1000],
]);

export function toRoman(n) {
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Value must be an integer between 1 and 3999');
  }
  let result = '';
  for (const [value, numeral] of NUMERALS) {
    while (n >= value) {
      result += numeral;
      n -= value;
    }
  }
  return result;
}

export function fromRoman(s) {
  if (typeof s !== 'string' || s.length === 0) {
    throw new Error('Invalid Roman numeral');
  }
  let total = 0;
  let prev = 0;
  for (let i = s.length - 1; i >= 0; i--) {
    const char = s[i];
    const value = ROMAN_VALUE.get(char);
    if (value === undefined) {
      throw new Error('Invalid Roman numeral');
    }
    if (value < prev) {
      total -= value;
    } else {
      total += value;
    }
    prev = value;
  }

  // Validate by re-encoding and checking round-trip
  // This catches malformed numerals like 'VX' (5), 'IIII' (4), 'IC' (99), etc.
  if (toRoman(total) !== s) {
    throw new Error('Invalid Roman numeral');
  }

  return total;
}

