// Find all function definitions in src/
const definitions = new Map(); // func -> array of {file, line}
for (const f of srcFiles) {
  const content = fs.readFileSync(f, 'utf8');
  const lines = content.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(/(?:export\s+)?function\s+(\w+)/);
    if (m) {
      const func = m[1];
      if (!definitions.has(func)) definitions.set(func, []);
      definitions.get(func).push({file: f, line: i});
    }
  }
}

const counts = new Map();
for (const func of definitions.keys()) counts.set(func, 0);

for (const f of allFiles) {
  const content = fs.readFileSync(f, 'utf8');
  const lines = content.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const codePart = lines[i].replace(/\/\/.*/, '');
    for (const func of definitions.keys()) {
